<script>window.initPentaxSubinsurance=window.initPentaxSubinsurance||function(scope){var root=jQuery(scope||document),insurance=root.find('.js-pentax-insurance').first(),sub=root.find('.js-pentax-subinsurance').first(),help=root.find('.js-pentax-subinsurance-help').first();if(!insurance.length||!sub.length)return;function filter(){var id=String(insurance.val()||''),visible=0;sub.find('option[data-insurance]').each(function(){var match=String(jQuery(this).data('insurance'))===id;jQuery(this).prop({'disabled':!match,'hidden':!match}).toggle(match);if(match)visible++;});if(sub.find('option:selected').prop('disabled'))sub.val('');sub.prop('disabled',visible===0);help.text(visible?visible+' subseguro(s) disponible(s) para el convenio seleccionado.':'Este convenio no tiene subseguros activos.');}insurance.on('change',filter);filter();};window.initPentaxProcedurePicker=window.initPentaxProcedurePicker||function(scope){var root=jQuery(scope||document),picker=root.find('.js-pentax-procedures').first(),help=root.find('.js-pentax-procedure-help').first();if(!picker.length)return;function update(){var count=(picker.val()||[]).length;help.text(count?(count===1?'1 procedimiento seleccionado.':count+' procedimientos seleccionados.')+' Puedes buscar y agregar más.':'Busca por nombre y selecciona uno o varios procedimientos.');}if(jQuery.fn.select2){picker.select2({theme:'bootstrap4',width:'100%',closeOnSelect:false,placeholder:picker.data('placeholder'),language:{noResults:function(){return 'No se encontraron procedimientos';},searching:function(){return 'Buscando…';}}});picker.on('change',update);}update();};document.addEventListener('DOMContentLoaded',function(){window.initPentaxSubinsurance(document);window.initPentaxProcedurePicker(document);});</script>
